using OpenFPS.Instruments;

namespace OpenFPS.AudioLab;

/// <summary>
/// --physics-replay [walks|drives|traffic|rail|ballistics|ricochet|all] [name=WALK] [track]
///
/// Runs the stage 0 physics guards (docs/PHYSICS_BOUNDARY.md) over the real maps and prints what each
/// stores: a walk's summary with its three parity risks (and its whole track with <c>track</c>), each drive's
/// last state, the traffic's and the train's movers, the ballistics and ricochet tables. Nothing is written: the stored
/// copies are regenerated by the tests on purpose (OPENFPS_PHYSICS_WRITE=1), as the sound guards are.
/// </summary>
public static class PhysicsReplaySpike
{
    public static PhysicsReplays.MapFolders Folders => new(LabPaths.Server("maps"), LabPaths.Server("maps", "places"), LabPaths.Server("prefabs"));

    public static int Run(string[] args)
    {
        Serilog.Log.Logger = new Serilog.LoggerConfiguration().MinimumLevel.Warning().CreateLogger();
        string what = args.FirstOrDefault(a => a is "walks" or "drives" or "traffic" or "rail" or "ballistics" or "ricochet" or "all") ?? "walks";
        string? only = args.FirstOrDefault(a => a.StartsWith("name="))?[5..];
        bool track = args.Contains("track");
        var maps = new Dictionary<string, PhysicsReplays.LoadedMap>();
        PhysicsReplays.LoadedMap Map(string id) => maps.TryGetValue(id, out var m) ? m : maps[id] = PhysicsReplays.Load(id, Folders);

        // hills map=ID: the steepest smooth 30 m of open ground within 400 m of the spawn, each way, for a
        // walk or a drive up a real slope.
        if (args.Contains("hills"))
        {
            string id = args.FirstOrDefault(a => a.StartsWith("map="))?[4..] ?? "magnolia_tx";
            var m = Map(id);
            var geo = m.Grid.Geometry!;
            var spawn = m.Maps.GetSpawnPoint(id).Position;
            var any = new OpenFPS.Geometry.AcceptAll();
            float Floor(float x, float z, out string mat)
            {
                float h = geo.FloorAt(x, z, 200f, OpenFPS.Geometry.GeometryLayers.Ground, ref any, out var hit);
                mat = h > -999f ? geo.SurfaceOf(hit.Solid).Material : "";
                return h;
            }
            var best = new List<(float Rise, float X, float Z, int Deg, string Mat)>();
            for (float x = spawn.X - 400f; x <= spawn.X + 400f; x += 5f)
                for (float z = spawn.Z - 400f; z <= spawn.Z + 400f; z += 5f)
                    foreach (int deg in new[] { 0, 45, 90, 135, 180, 225, 270, 315 })
                    {
                        float a = deg * MathF.PI / 180f, dx = MathF.Sin(a), dz = MathF.Cos(a);
                        float h0 = Floor(x, z, out string mat0), last = h0;
                        bool smooth = h0 > -999f;
                        for (int s = 1; smooth && s <= 30; s++)
                        {
                            float h = Floor(x + dx * s, z + dz * s, out string mat);
                            smooth = h > -999f && MathF.Abs(h - last) < 0.12f && mat == mat0;
                            last = h;
                        }
                        if (smooth && last - h0 > 0.5f) best.Add((last - h0, x, z, deg, mat0));
                    }
            foreach (var b in best.OrderByDescending(b => b.Rise).Take(15))
                Console.WriteLine($"  rise {b.Rise:F2} m over 30 m from /tp {b.X:F1} {b.Z:F1} heading {b.Deg} on {b.Mat}");
            return 0;
        }

        if (what is "walks" or "all")
        {
            Console.WriteLine(PhysicsReplays.WalkSummaryHeader + "\treproduction_misses\tseconds");
            foreach (var w in PhysicsReplays.Walks)
            {
                if (only != null && w.Name != only) continue;
                var clock = System.Diagnostics.Stopwatch.StartNew();
                var run = PhysicsReplays.Walk(Map(w.Map), w);
                Console.WriteLine($"{PhysicsReplays.SummaryLine(run)}\t{run.ReproductionMisses}\t{clock.Elapsed.TotalSeconds:F1}");
                if (run.FirstGatherDifference != null) Console.WriteLine($"  gathers first differ: {run.FirstGatherDifference}");
                if (track) Console.Write(PhysicsReplays.Track(run));
            }
        }
        if (what is "drives" or "all")
            foreach (var d in PhysicsReplays.Drives)
            {
                if (only != null && d.Name != only) continue;
                var lines = PhysicsReplays.Drive(Map(d.Map), d).TrimEnd('\n').Split('\n');
                if (track) foreach (var l in lines) Console.WriteLine(l);
                else Console.WriteLine($"{d.Name}: {lines.Length - 3} ticks; last {lines[^1]}");
            }
        if (what is "traffic" or "all")
        {
            var text = PhysicsReplays.Traffic(PhysicsReplays.Load("city", Folders));
            var lines = text.TrimEnd('\n').Split('\n');
            Console.WriteLine($"traffic: {lines.Length - 1} rows, {lines.Skip(1).Select(l => l.Split('\t')[1]).Distinct().Count()} movers, {text.Length / 1024} KB");
            if (track) Console.Write(text);
        }
        if (what is "rail" or "all")
        {
            var text = PhysicsReplays.Rail(PhysicsReplays.Load("city", Folders));
            var lines = text.TrimEnd('\n').Split('\n');
            Console.WriteLine($"rail: {lines.Length - 1} rows, {lines.Skip(1).Select(l => l.Split('\t')[1]).Distinct().Count()} movers, {text.Length / 1024} KB");
            if (track) Console.Write(text);
        }
        if (what is "ballistics" or "all") Console.Write(PhysicsReplays.BallisticsTable());
        if (what is "ricochet" or "all") Console.Write(PhysicsReplays.RicochetTable());
        return 0;
    }
}
